"""Complete 24 original questions across gout, CPPD and basic calcium phosphate disease."""
from create_rheum_gout import rows,q,G,IM,CP,ref
from qbank_authoring import finalize

q('A patient with gout and established coronary disease cannot tolerate allopurinol and is considering febuxostat. Which counseling is appropriate?', 'Discuss its cardiovascular safety warning, the evidence and alternatives in an individualized benefit-risk decision',[
 ('Febuxostat has no cardiovascular warning and requires no discussion of his history','The US label includes a boxed warning based on the CARES safety findings.'),('Febuxostat and allopurinol are both uricosurics, so prior coronary disease is the only relevant factor','Both are xanthine oxidase inhibitors; renal, drug-interaction and gout-control issues also matter.'),('All patients with any cardiovascular risk must instead receive pegloticase immediately','Pegloticase is reserved for selected uncontrolled refractory gout, not every cardiovascular-risk scenario.')],
 'Interpret a safety warning with the individual patient','**Febuxostat carries a US cardiovascular-death warning in gout patients with established cardiovascular disease.**',['Different trials and populations have produced a nuanced evidence base.','Document the reason allopurinol is unsuitable and discuss feasible alternatives.'], '**Do not choose or reject therapy without assessing the competing risks of uncontrolled gout.**',['Follow local regulatory indications.','Review interacting drugs and arrange urate and safety monitoring.'],[['Febuxostat','Xanthine oxidase inhibitor'],['Established cardiovascular disease','Specific warning discussion'],['Selection','Individual benefit-risk assessment']],[ref('DailyMed: febuxostat prescribing information','https://www.dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=14f1555c-2565-42c7-b3f5-dd5f03fed67a&type=display')],style='clinical_scenario')

q('A patient taking azathioprine is prescribed allopurinol at a routine gout dose. Which potentially serious interaction needs immediate attention?', 'Inhibition of thiopurine metabolism with increased risk of profound myelosuppression',[
 ('Rapid loss of all thiopurine activity requiring automatic dose doubling','The interaction increases toxic exposure rather than eliminating efficacy.'),('Selective precipitation of calcium pyrophosphate crystals','This is not the principal interaction.'),('Reduced colchicine absorption despite no colchicine exposure','This does not explain the concern for these two medications.')],
 'Xanthine oxidase inhibition changes thiopurine exposure','**Allopurinol can markedly increase azathioprine/mercaptopurine toxicity.**',['Intentional coadministration in selected specialist protocols uses major thiopurine dose reduction and close monitoring.','Routine full-dose coprescribing without a plan is unsafe.'], '**Review both prescriptions before continuing.**',['Obtain blood counts and assess for infection, ulcers or bleeding if exposure has occurred.','Febuxostat also has a major thiopurine interaction and is not a simple safe substitution.'],[['Allopurinol','Inhibits a thiopurine metabolic pathway'],['Full-dose thiopurine','Severe marrow toxicity risk'],['Planned combination','Specialist dose adjustment and monitoring']],[ref('Medsafe: allopurinol-thiopurine interaction','https://www.medsafe.govt.nz/profs/PUArticles/September2020/Allopurinol-life-threatening-interaction-azathioprine-mercaptopurine.html')],style='clinical_scenario')

q('Which statement about pegloticase for uncontrolled refractory gout is correct?', 'It is a uricase therapy contraindicated in G6PD deficiency because of hemolysis and methemoglobinemia risk',[
 ('It is first-line oral treatment for asymptomatic hyperuricemia','It is an intravenous agent for a selected refractory gout population.'),('It inhibits xanthine oxidase by the same mechanism as allopurinol','Uricase converts urate to allantoin rather than inhibiting urate production.'),('It needs no preinfusion serum urate monitoring because infusion reactions are unrelated to loss of response','Loss of urate-lowering response can signal antibody-related infusion reaction risk.')],
 'Reserve uricase for the appropriate refractory population','**Pegloticase enzymatically converts urate to a more soluble metabolite.**',['Screen for G6PD deficiency according to the product requirements before treatment.','The current US regimen generally includes methotrexate unless contraindicated or not clinically appropriate, to reduce immunogenicity.'], '**Monitor urate before infusions and follow stopping rules for loss of response.**',['Provide required premedication and observation for infusion reactions.','This is not routine therapy for mild gout or an isolated raised urate.'],[['Mechanism','Uricase'],['G6PD deficiency','Contraindication'],['Rising preinfusion urate','May signal loss of response and infusion risk']],[ref('DailyMed: Krystexxa prescribing information, revised June 2026','https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6e566303-d93a-4130-b764-25749829aa95')])

q('An older woman develops an acutely inflamed wrist after surgery. Aspirate shows rhomboid crystals with weak positive birefringence. What is the most likely diagnosis?', 'Acute calcium pyrophosphate crystal arthritis',[
 ('Monosodium urate crystal arthritis','MSU crystals classically have negative birefringence and a needle shape.'),('Basic calcium phosphate deposition disease','BCP deposits are generally not identifiable as these birefringent rhomboid crystals.'),('Cholesterol crystal arthritis','Cholesterol has a different plate-like morphology.')],
 'Recognize CPP crystal morphology','**CPP crystals are often rhomboid or rod-shaped and weakly positively birefringent.**',['Knees and wrists are commonly affected.','Surgery or acute illness can precipitate an attack in a susceptible joint.'], '**Assess for infection as well as crystals.**',['CPP crystals may be difficult to detect because birefringence can be weak.','A negative microscopy result does not exclude CPPD when sampling or expertise is limited.'],[['CPP','Weak positive, often rhomboid'],['MSU','Strong negative, needle-shaped'],['BCP','Not routinely birefringent']],[CP,IM],style='clinical_scenario')

q('A febrile patient has a hot knee with CPP crystals in the aspirate. Which additional step remains important?', 'Send appropriate synovial microbiology and evaluate for concomitant septic arthritis',[
 ('Discard cultures because crystal detection excludes infection','Crystal and infectious arthritis can coexist.'),('Use serum urate as the definitive infection test','Urate does not establish or exclude joint infection.'),('Inject intra-articular glucocorticoid before considering the infectious possibility','Injection should wait until infection has been appropriately excluded.')],
 'Crystals answer one question but not every question','**Crystal identification does not make a septic joint impossible.**',['Fever, immunosuppression, bacteremia and systemic instability increase concern.','Synovial leukocyte counts overlap among crystal disease and infection.'], '**Treat suspected infection promptly when the clinical probability warrants it.**',['Obtain cultures before antibiotics when feasible without dangerous delay.','Arrange drainage and antibiotic treatment if infection is established or strongly suspected.'],[['Crystals','Deposition is present'],['Culture','Investigates infection'],['Injection','Requires appropriate infection exclusion']],[IM],style='clinical_scenario')

q('An older adult develops acute severe neck pain, restricted rotation, fever and raised CRP. CT shows crown-like calcification around the odontoid process. Which diagnosis best fits?', 'Crowned dens syndrome',[
 ('Atlantoaxial rheumatoid instability','This involves ligamentous/joint damage and instability rather than the stated peridentoid calcification syndrome.'),('Cervical disc prolapse','This does not account for the characteristic calcification pattern and inflammatory presentation.'),('Diffuse idiopathic skeletal hyperostosis','Flowing anterolateral ossification is different from an acute peridentoid crystal syndrome.')],
 'Consider axial crystal disease in an acute inflammatory neck syndrome','**Crowned dens syndrome commonly reflects CPP deposition around the odontoid.**',['CT is useful for identifying the characteristic deposits.','Meningitis, infection and other emergencies remain important alternatives depending on the presentation.'], '**Correlate the imaging with the acute clinical syndrome.**',['Incidental calcification alone does not explain every symptom.','Anti-inflammatory treatment is selected according to comorbidity after dangerous mimics are assessed.'],[['CT','Peridentoid calcification'],['Clinical presentation','Acute inflammatory neck pain'],['Differential','Infection and other cervical pathology']],[CP,IM],style='clinical_scenario')

q('A 44-year-old has recurrent CPP crystal arthritis and extensive chondrocalcinosis. Which metabolic evaluation is particularly relevant?', 'Calcium, magnesium, alkaline phosphatase and iron studies',[
 ('Only serial anti-CCP titers','These do not screen the principal metabolic associations of early CPPD.'),('Only serum urate and a 24-hour urine urate','These address urate biology rather than the range of CPPD associations.'),('Only antistreptolysin O and rheumatoid factor','These do not provide the appropriate metabolic screen.')],
 'Young or extensive CPPD should prompt an association search','**Hemochromatosis, hyperparathyroidism, hypomagnesemia and hypophosphatasia are relevant associations.**',['Use calcium/PTH, magnesium, alkaline phosphatase and iron testing in the appropriate context.','A family history may support an inherited predisposition.'], '**Treat a discovered metabolic disorder for its own clinical importance.**',['Correction does not guarantee disappearance of established cartilage deposits.','Avoid labeling all early chondrocalcinosis as age-related degeneration.'],[['High calcium/PTH','Consider hyperparathyroidism'],['Low magnesium','Recognized CPPD association'],['Iron overload/low ALP','Consider hemochromatosis/hypophosphatasia']],[CP])

q('Which arthropathy pattern should particularly prompt iron-overload assessment?', 'Second/third MCP disease with hook-like osteophytes and chondrocalcinosis',[
 ('Isolated first-MTP acute arthritis with proven MSU crystals','This establishes gout rather than a characteristic iron-overload pattern.'),('Symmetric wrist/MCP marginal erosions with strong ACPA positivity','This supports an RA phenotype more directly.'),('DIP central erosions with prominent Heberden nodes','This favors erosive hand osteoarthritis.')],
 'Recognize a hemochromatosis-associated joint pattern','**MCP involvement with hook osteophytes can be an important clue to iron overload.**',['CPP deposition can coexist with hemochromatosis arthropathy.','Assess transferrin saturation and ferritin with attention to inflammation and liver disease.'], '**Investigate systemic iron overload rather than treating the joints in isolation.**',['Family and genetic assessment may be appropriate after biochemical evaluation.','Joint disease may persist despite treatment of iron overload.'],[['MCP hook osteophytes','Iron-overload clue'],['Chondrocalcinosis','CPP deposition may coexist'],['Iron studies','Assess systemic disease']],[CP])

q('A patient with a single acutely inflamed CPPD knee has had infection appropriately excluded. Which treatment is reasonable?', 'Aspiration and intra-articular glucocorticoid, with systemic anti-inflammatory options chosen by comorbidity',[
 ('Allopurinol to dissolve CPP crystals','Xanthine oxidase inhibition does not dissolve calcium pyrophosphate deposits.'),('Antibiotics for every culture-negative CPP attack','Antibiotics do not treat sterile crystal inflammation.'),('Routine joint replacement during the first flare','Surgery is not the standard acute treatment for an uncomplicated crystal attack.')],
 'Treat the inflammation, not serum urate','**CPP crystal attacks are treated with anti-inflammatory strategies.**',['Aspiration can relieve an effusion and provide diagnostic material.','Colchicine, NSAIDs or systemic glucocorticoids may be selected when appropriate, accounting for the older patient population and comorbidities.'], '**Distinguish acute attack care from chronic joint management.**',['Recurrent episodes may warrant prophylaxis discussions.','There is no established routine urate-lowering equivalent that removes CPP deposits.'],[['Acute CPP flare','Anti-inflammatory care'],['Allopurinol','Does not target CPP deposits'],['Chronic CPPD','Individualized symptom and recurrence management']],[ref('EULAR CPPD management recommendations','https://ard.bmj.com/content/70/4/571')],style='clinical_scenario')

q('An asymptomatic older adult has incidental knee chondrocalcinosis on an X-ray. What is usually appropriate?', 'No specific anti-inflammatory treatment solely for the imaging finding',[
 ('Start indefinite colchicine in every patient','Prophylaxis is not routinely indicated for an incidental asymptomatic deposit.'),('Start allopurinol to normalize cartilage calcium','Allopurinol does not treat CPP deposition.'),('Inject both knees despite the absence of symptoms','There is no symptomatic inflammatory target and the procedure adds unnecessary risk.')],
 'An imaging deposit is not always symptomatic disease','**Asymptomatic chondrocalcinosis does not itself require anti-inflammatory therapy.**',['Interpret future symptoms on their merits rather than attributing all pain to the deposit.','Consider metabolic associations when age, extent or other features make them relevant.'], '**Explain the finding without creating unnecessary treatment.**',['Offer assessment if acute swelling or new symptoms occur.','Manage coexisting osteoarthritis according to its own functional burden.'],[['Incidental deposit','Often no specific treatment'],['Acute hot joint','Evaluate the cause'],['Metabolic clues','Investigate selectively']],[IM,ref('EULAR CPPD management recommendations','https://ard.bmj.com/content/70/4/571')])

q('An elderly woman has a large recurrent relatively low-cell-count shoulder effusion, severe glenohumeral destruction and a massive rotator cuff tear. Which crystal disorder is most characteristic?', 'Basic calcium phosphate-associated Milwaukee shoulder syndrome',[
 ('Classic tophaceous gout as the only plausible cause','Gout can affect unusual joints but does not best match this characteristic cuff-tear destructive phenotype.'),('Acute CPP arthritis defined solely by a strongly negative birefringence result','Strongly negative needle crystals suggest MSU, and the stated microscopy claim is incorrect.'),('Oxalate arthropathy without any renal or metabolic context','Oxalate deposition is a different disorder, often linked to advanced renal disease or hyperoxaluria.')],
 'A destructive shoulder can have a crystal-associated mechanism','**Milwaukee shoulder syndrome is associated with BCP, including hydroxyapatite, and rotator cuff failure.**',['Routine polarized microscopy may not reveal these very small nonbirefringent deposits.','Calcium-sensitive stains such as alizarin red can support detection but require appropriate interpretation.'], '**Exclude infection and other causes of destructive arthropathy.**',['Fluid analysis and imaging should be correlated.','Management addresses pain, recurrent effusion and mechanical function.'],[['Milwaukee shoulder','Destruction with cuff pathology'],['BCP crystals','Not routinely birefringent'],['Alizarin red','Supports calcium-containing deposit detection']],[ref('Original Milwaukee shoulder clinical study','https://pubmed.ncbi.nlm.nih.gov/6260120/'),ref('Milwaukee shoulder clinical case','https://pmc.ncbi.nlm.nih.gov/articles/PMC3914332/')],style='clinical_scenario')

q('Which crystal is most closely associated with typical calcific rotator cuff tendinopathy?', 'Basic calcium phosphate, including hydroxyapatite',[
 ('Monosodium urate','Urate deposition causes gout and tophi rather than the usual calcific tendinopathy deposit.'),('Calcium pyrophosphate','CPPD is more characteristically associated with cartilage deposition and its related arthritis phenotypes.'),('Cholesterol','Cholesterol crystals are not the usual deposit in calcific cuff tendinopathy.')],
 'Identify the periarticular deposition process','**BCP deposits can occur in rotator cuff tendons and provoke acute periarticular inflammation.**',['Pain can be intense during a resorptive phase.','The lesion is periarticular rather than necessarily an intra-articular synovitis.'], '**Use the clinical examination and appropriate imaging to localize the problem.**',['Management can include analgesia, rehabilitation and selected image-guided procedures.','Do not prescribe gout ULT solely because a tendon calcification is present.'],[['Calcific cuff tendinopathy','BCP deposition'],['Gout','MSU'],['Chondrocalcinosis','Often CPP deposition']],[IM])

if __name__=='__main__':finalize('Rheumatology',3,'Crystal Arthritis','rheum-crystal',rows,24)
